# =============================================================================
# Dockerfile.map — FICSIT AuditBot image WITH the embedded satisfactorymap page
# =============================================================================
# The default ./Dockerfile ships a lean image WITHOUT the map bundle (the map
# route 404s, and headless rendering is disabled). This variant additionally
# builds the satisfactorymap static bundle and ships a Chromium-capable runtime
# so the "Map" page and the Discord map-image renderer work.
#
# Game-derived data (item/building JSONs, icons, the map image) is NOT in this
# repo (Coffee Stain assets, too large to commit -- the archive is 127 MB, over
# GitHub's 100 MB file limit). It is fetched during the build from the upstream
# release, pinned by URL + SHA-256 (the same source the upstream build uses), so
# the finished image contains everything and the app is ready to use.
#
#   docker build -f Dockerfile.map -t ficsit-auditbot:map .
#
# Requires the git submodule to be checked out:
#     git submodule update --init --recursive
# =============================================================================

# ---- App build (TypeScript -> dist/) ----
FROM node:22-alpine AS app-build
WORKDIR /app
ENV PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD=1
COPY package*.json ./
RUN npm ci
COPY tsconfig.json ./
COPY src ./src
RUN npm run build

# ---- Map build (Rust -> WASM + static site) ----
FROM rust:1-bookworm AS map-build
WORKDIR /build

# Pinned game-data archive + wasm-pack (same versions the upstream build uses).
ARG GAME_DATA_URL="https://github.com/valentinps/satisfactorymap/releases/download/game-data-v1/game_data.zip"
ARG GAME_DATA_SHA256="75b2087fae82ff00a1d36fccebd0970550e5ccebfad6d2b159c2838718cd13d6"
ARG WASM_PACK_VERSION="v0.15.0"

RUN apt-get update \
 && apt-get install -y --no-install-recommends python3 python3-pip curl ca-certificates \
 && rm -rf /var/lib/apt/lists/* \
 && pip3 install --break-system-packages "Pillow>=10,<12"

# Pinned prebuilt wasm-pack binary (faster + reproducible vs. cargo install).
RUN curl --proto '=https' --tlsv1.2 -sSfL -o /tmp/wasm-pack.tar.gz \
      "https://github.com/rustwasm/wasm-pack/releases/download/${WASM_PACK_VERSION}/wasm-pack-${WASM_PACK_VERSION}-x86_64-unknown-linux-musl.tar.gz" \
 && tar -xzf /tmp/wasm-pack.tar.gz --strip-components=1 -C /usr/local/bin \
      "wasm-pack-${WASM_PACK_VERSION}-x86_64-unknown-linux-musl/wasm-pack" \
 && rm -f /tmp/wasm-pack.tar.gz \
 && rustup target add wasm32-unknown-unknown

# The vendored, AGPL-licensed map source (submodule; checkout with
# `git submodule update --init --recursive`).
COPY third_party/satisfactorymap ./satisfactorymap

# Fetch + verify + unpack the game-derived data (icons, map image, JSONs).
RUN cd satisfactorymap \
 && curl --proto '=https' --tlsv1.2 -sSfL -o game_data.zip "${GAME_DATA_URL}" \
 && echo "${GAME_DATA_SHA256}  game_data.zip" | sha256sum -c - \
 && python3 game_data/package_game_data.py unpack game_data.zip \
 && rm -f game_data.zip

# Layer the AuditBot integration overlay onto the frontend before assembling.
COPY map-integration/overlay/auditbot.js ./satisfactorymap/map/static/map/auditbot.js
RUN sed -i 's#</body>#  <script src="auditbot.js"></script>\n</body>#' \
        satisfactorymap/map/static/map/index.html

# Assemble the deployable static site into dist/.
RUN cd satisfactorymap && python3 tools/build_site.py

# ---- Runtime (Chromium-capable, for headless map rendering) ----
# Keep this tag in sync with the "playwright" version pinned in package.json.
FROM mcr.microsoft.com/playwright:v1.48.0-jammy AS runtime
WORKDIR /app
# Browsers are preinstalled in the base image; don't re-download them on npm ci.
ENV NODE_ENV=production \
    PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD=1

# Production dependencies (Playwright's browsers are already in the base image).
COPY package*.json ./
RUN npm ci --omit=dev && npm cache clean --force

# App output + static frontend, then the built map bundle at public/map/.
COPY --from=app-build /app/dist ./dist
COPY public ./public
COPY --from=map-build /build/satisfactorymap/dist ./public/map
COPY docs/bundled-en-US.json /opt/ficsit-docs/en-US.json
COPY docker-entrypoint.sh /usr/local/bin/ficsit-entrypoint.sh
RUN chmod +x /usr/local/bin/ficsit-entrypoint.sh

ENV DATA_DIR=/data \
    SAVES_DIR=/saves \
    WEB_PORT=8080 \
    WEB_ENABLED=true \
    WATCH_USE_POLLING=true \
    POST_TO_DISCORD=false \
    MAP_IMAGE_ENABLED=false

EXPOSE 8080
VOLUME ["/data"]
ENTRYPOINT ["/usr/local/bin/ficsit-entrypoint.sh"]
CMD ["node", "dist/index.js"]
